'use client';
import { useRef, useState } from 'react';
import { services } from './services';

export function VisitPlanner({ initialService = '' }) {
  const [summary, setSummary] = useState('');
  const [copyStatus, setCopyStatus] = useState('');
  const output = useRef(null);
  function prepare(event) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    const name = String(data.get('name')).trim();
    if (!name) { event.currentTarget.elements.name.setCustomValidity('Please enter your name.'); event.currentTarget.elements.name.reportValidity(); return; }
    setSummary(`Hello, my name is ${name}. I would like to enquire about ${data.get('service')}. My preferred day is ${data.get('day') || 'flexible'} and my preferred time is ${data.get('time')}. Please confirm availability and the consultation fee.`);
    setCopyStatus('');
    requestAnimationFrame(() => output.current?.focus());
  }
  async function copy() {
    try { await navigator.clipboard.writeText(summary); setCopyStatus('Your enquiry has been copied.'); }
    catch { output.current?.focus(); output.current?.select(); setCopyStatus('Select and copy the enquiry text below.'); }
  }
  return <section className="visit-planner" aria-labelledby="planner-heading"><div className="planner-intro"><span className="extra-kicker">Let’s plan your visit</span><h2 id="planner-heading">A little preparation.<br />An easier first step.</h2><p>Put your appointment preferences together, then call the clinic to arrange your visit.</p><div className="planner-contact"><span>Speak to the clinic</span><a href="tel:+923203771995">+92 320 3771995 ↗</a><small>Call to confirm opening hours and availability.</small></div></div><form onSubmit={prepare} onChange={() => { setSummary(''); setCopyStatus(''); }}><div className="planner-fields"><label>Your name<input name="name" autoComplete="given-name" placeholder="Your first name" required maxLength={80} onInput={e => e.currentTarget.setCustomValidity('')} /></label><label>Interested in<select name="service" defaultValue={initialService} required><option value="">Choose a service</option>{services.map(s => <option key={s.slug} value={s.title}>{s.title}</option>)}</select></label><label>Preferred day<select name="day" defaultValue="flexible">{['flexible', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'].map(d => <option key={d} value={d}>{d === 'flexible' ? 'I’m flexible' : d}</option>)}</select></label><label>Preferred time<select name="time" defaultValue="flexible"><option value="flexible">I’m flexible</option><option>Morning</option><option>Afternoon</option><option>Evening</option></select></label></div><button className="button" type="submit">Prepare my enquiry ↗</button><p className="planner-note">This prepares a note on your device. Nothing is sent or booked; the clinic must confirm your appointment.</p>{summary && <div className="planner-result"><label htmlFor="enquiry-summary">Your enquiry is ready</label><textarea ref={output} id="enquiry-summary" readOnly value={summary} rows={5} /><div><button type="button" onClick={copy}>Copy enquiry</button><a href="tel:+923203771995">Call the clinic ↗</a></div><p role="status">{copyStatus}</p></div>}</form></section>;
}

export function VisitChecklist() {
  const [checked, setChecked] = useState([]);
  const items = ['Write down the questions I want to ask', 'Ask which previous dental records to bring', 'Confirm the consultation fee and appointment time', 'Check the clinic location and plan my journey'];
  return <section className="visit-checklist"><div><span className="extra-kicker">Your first visit</span><h2>Feel a little<br />more prepared.</h2><p>A simple checklist for your next conversation with the clinic.</p><span className="checklist-count" role="status">{checked.length} of {items.length} ready</span><div className="checklist-track" aria-hidden="true"><span style={{ width: `${checked.length / items.length * 100}%` }} /></div></div><div>{items.map((item,i) => <label key={item} className={checked.includes(i) ? 'is-checked' : ''}><input type="checkbox" checked={checked.includes(i)} onChange={e => setChecked(e.target.checked ? [...checked,i] : checked.filter(n => n !== i))} /><span>{item}</span></label>)}{checked.length === items.length && <p className="checklist-done" role="status">Your checklist is complete. You’re ready to make the call.</p>}</div></section>;
}

export function VisitLocation() {
 return <section className="visit-location"><div><span className="extra-kicker">Close to home</span><h2>Find your way<br />to a familiar smile.</h2><p>Allama Iqbal Road, opposite City Book Depot, above National Bank of Pakistan, New Mirpur City, AJK.</p><a className="button" href="https://maps.app.goo.gl/P7CC4EacYpLexbNC8" target="_blank" rel="noreferrer">Get directions ↗</a></div><div className="location-details"><article><span>01</span><div><h3>Call before you visit</h3><p>Confirm your appointment time and the dentist’s availability.</p></div></article><article><span>02</span><div><h3>Plan your arrival</h3><p>Find us above National Bank of Pakistan, opposite City Book Depot.</p></div></article><article><span>03</span><div><h3>Need a little help?</h3><p>Call <a href="tel:+923203771995">+92 320 3771995</a> for directions or appointment enquiries.</p></div></article></div></section>;
}
