import Image from 'next/image';

/** Responsive local photography; defer off-screen images by default. */
export default function OptimizedClinicImage({ src, alt, className, priority = false }) {
  return <Image
    src={src}
    alt={alt}
    className={className}
    width={1600}
    height={1067}
    sizes="(max-width: 800px) calc(100vw - 40px), (max-width: 1200px) 60vw, 800px"
    quality={75}
    loading={priority ? 'eager' : 'lazy'}
    fetchPriority={priority ? 'high' : 'auto'}
    decoding="async"
  />;
}
